import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String panel = next();
        int q = nextInt();
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < q; t++) {
            String code = next();
            for (int cut = 1; cut < code.length(); cut++) {
                // Parse the index part; any value beyond the panel length cannot match.
                long start = 0;
                for (int k = 0; k < cut; k++) start = Math.min(start * 10 + (code.charAt(k) - '0'), 1_000_000_000L);
                String pattern = code.substring(cut);
                boolean match = start + pattern.length() <= panel.length()
                    && panel.startsWith(pattern, (int) start);
                out.append(match ? pattern : "not found").append('\n');
            }
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	panel := string(token())
	q := nextInt()
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for t := 0; t < q; t++ {
		code := string(token())
		for cut := 1; cut < len(code); cut++ {
			// Parse the index part; any value beyond the panel length cannot match.
			start := 0
			for k := 0; k < cut; k++ {
				start = min(start*10+int(code[k]-'0'), 1_000_000_000)
			}
			pattern := code[cut:]
			if start+len(pattern) <= len(panel) && panel[start:start+len(pattern)] == pattern {
				w.WriteString(pattern)
			} else {
				w.WriteString("not found")
			}
			w.WriteByte('\n')
		}
	}
}
